    yi: ['朦胧的烟雾笼罩着寒冷的河水，月光笼罩着岸边的白沙，夜里我把船停在秦淮河边，靠近酒家。', '卖唱的歌女不懂得亡国的怨恨，还在河对岸唱着《玉树后庭花》。'],
