    yi: ['空旷的山林刚下过一场雨，到了傍晚，天气已透出秋天的凉意。', '明月从松树间洒下清光，清澈的泉水在石头上流淌。', '竹林里传来说笑声，是洗衣的姑娘们回来了；莲叶摇动，是渔船顺流而下。', '任凭春天的花草凋谢吧，这秋天的山中，我自可以留下来。'],
    bg: '王维中年以后在终南山下的蓝田辋川买了别墅，过着半官半隐的生活。这首诗写辋川秋天傍晚雨后的景色，一般认为是这一时期写的。',
