      '校尉的紧急军书飞过大沙漠，敌人首领的战火已经照亮了狼山。',
      '山河一片萧条，一直到边疆的尽头，敌人的骑兵像狂风暴雨一样冲杀过来。',
      '战士们在阵前拼杀，死伤了一大半，将军的营帐里却还有美人在歌舞。',
      '深秋的大漠，边塞的草都枯萎了，孤城笼罩在夕阳里，能作战的士兵越来越少。',
      '将领受到朝廷的恩宠，常常轻视敌人；士兵们在关山拼尽了力气，还是没能解围。',
      '穿着铠甲的战士在远方守边，辛苦了很久，家里的妻子自从离别以后，一定常常流泪。',
      '少妇在城南思念得肝肠寸断，征人在蓟北也只能白白地回头遥望。',
