    yi: ['送你送了这么远，就从这里分别吧，青山也空含着离别的情意。什么时候我们才能再举杯共饮？昨夜还在月下一起同行。', '各郡的百姓都称颂你，舍不得你走，你历经三朝，出将入相，十分荣耀。我独自回到江边的村子，寂寞地度过余生。'],
